import { get } from "@vercel/blob";
import { NextResponse } from "next/server";
import { verifyFilePath } from "@/lib/checkout/server/tokens";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Owner-only download link (used in the "Documents received" email).
// The link only works with the secret signature generated by the server.
export async function GET(request: Request) {
  const url = new URL(request.url);
  const pathname = url.searchParams.get("p") || "";
  const sig = url.searchParams.get("s");

  if (!pathname.startsWith("orders/") || pathname.includes("..") || !verifyFilePath(pathname, sig)) {
    return new NextResponse("Link not valid", { status: 403 });
  }

  const result = await get(pathname, { access: "private" }).catch(() => null);
  if (!result || result.statusCode !== 200) {
    return new NextResponse("File not found", { status: 404 });
  }

  const filename = pathname.split("/").pop() || "document";
  return new NextResponse(result.stream, {
    headers: {
      "Content-Type": result.blob.contentType || "application/octet-stream",
      "Content-Disposition": `inline; filename="${filename.replace(/"/g, "")}"`,
      "X-Content-Type-Options": "nosniff",
      "Cache-Control": "private, no-store",
      "X-Robots-Tag": "noindex",
    },
  });
}
